//! 🔗️ Bound encoding lends the original unbound bytes and temporarily stages the exact shared group field.
use super::*;
use semio_framework_dsl_record::{BorrowedDslRecord,native_encoding::{FieldProjectionSource,FieldProjectionView as View}};
use semio_framework_pack_json::ArtifactCanonicalJsonTree;

struct BoundSource<'a>{wire:&'a DurableUnboundOneItemOutcomeV1,group:&'a str,edit:&'a[u8],digest:&'a[u8;32],generation:u64,revision:&'a[u8;32]}
impl BorrowedDslRecord for BoundSource<'_>{const RECORD:semio_framework_dsl_record::BorrowedRecordSpec=DurableBoundOneItemOutcomeV1::RECORD;}
const IDS:[u16;15]={let mut ids=[0;15];let mut index=0;while index<15{ids[index]=DurableBoundOneItemOutcomeV1::RECORD.fields[index].id;index+=1;}ids};
impl FieldProjectionSource for BoundSource<'_>{
    fn projection_identity(&self)->usize{self.wire as *const _ as usize}
    fn projection_view(&self,path:&[usize])->Result<View<'_>,ValueError>{if path.is_empty(){return Ok(View::Record(&IDS));}let tail=&path[1..];match path[0]{0 if tail.is_empty()=>Ok(View::Text(DURABLE_OWNED_GROUP_BOUND_OUTCOME_SCHEMA_V1)),1=>DslField::projection_view(&self.wire.recovery_schema,tail),2=>DslField::projection_view(&self.wire.operation,tail),3=>DslField::projection_view(&self.wire.base_generation,tail),4=>DslField::projection_view(&self.wire.base_revision,tail),5=>DslField::projection_view(&self.wire.base_applied_edit_count,tail),6=>DslField::projection_view(&self.wire.next_sequence_number,tail),7 if tail.is_empty()=>Ok(View::Bytes(&self.wire.next_clock_canonical_json)),8=>DslField::projection_view(&self.wire.actor,tail),9 if tail.is_empty()=>Ok(View::Text(self.group)),10 if tail.is_empty()=>Ok(View::Bytes(self.edit)),11 if tail.is_empty()=>Ok(View::Bytes(&self.wire.post_snapshot_pack)),12=>DslField::projection_view(self.digest,tail),13=>DslField::projection_view(&self.generation,tail),14=>DslField::projection_view(self.revision,tail),_=>Err(semio_framework_dsl_record::native_encoding::projection_path_error())}}
}
#[derive(Default)]
pub struct DurableBoundPlanningV1{group:Option<String>,json:DurableCanonicalOutputV1,wire_json:DurableCanonicalOutputV1,edit:Option<Vec<u8>>,wire_edit:Option<Vec<u8>>,encoder:DurablePackOutputV1,pack:Option<Vec<u8>>,hash:semio_framework_hash::Sha256,offset:usize,digest:[u8;32],post_revision:[u8;32],phase:u8,closing:Option<semio_framework_value::retirement::controlled::ControlledRetirement<DurablePlanningOutputV1>>}
impl DurableBoundPlanningV1{
    pub fn advance<P: ValueToValue,M:StoreMutation<P>+ArtifactCanonicalJsonTree+ValueToValue>(&mut self,prepared:&mut ArtifactStoreOneItemPrepared<P,M>,wire:&DurableUnboundOneItemOutcomeV1,store:&StorePartsRef<'_,P,M>,group:&str,grant:RetainedCloneGrant,native:&mut NativeEncodeControl<'_>)->Result<(Option<DurableStoreBindingPlanV1>,RetainedCloneProgress),DurableOwnedGroupDecisionError>{
        let error=DurableOwnedGroupDecisionError::Retirement;
        let mut receipt=RetainedCloneProgress{copied_items:1,..Default::default()};
        match self.phase{
            0=>{if !valid_hash(group){return Err(DurableOwnedGroupDecisionError::InvalidHash);}let authority=prepared.authority();authority.validate_prepared(prepared).map_err(error)?;if authority.group_id().is_some(){return Err(DurableOwnedGroupDecisionError::InvalidOutcome);}store_post_revision(store,authority,[0;32])?;let demand=RetirementDemand{capacity_bytes:64,..copy(size_of::<String>()+64+size_of::<u8>())};if !permit(demand,grant){return Ok((None,Default::default()));}native.admit_turn_capacity(grant.maximum_capacity_bytes).map_err(error)?;self.group=Some(native.copy_text(group).map_err(error)?);self.phase=1;receipt.copied_bytes=demand.copy_bytes;receipt.retained_capacity_bytes=64;},
            1=>{let local=2*size_of::<Option<String>>();let demand=self.json.next_demand();if grant.maximum_items==0||grant.maximum_copy_bytes<demand.copy_bytes+local||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_depth<demand.depth{return Ok((None,Default::default()));}let identity=self.group.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;let result=semio_framework_os_store_one_item_publication::ArtifactStorePreparedBinding::inspect_group(prepared,identity,grant,|original|self.json.advance(semio_framework_os_store_one_item_publication::lifted_prepared_operation_wire::ArtifactCanonicalTreeSource::view(original.edit()),DURABLE_OWNED_GROUP_RECOVERY_PACK_MAX_BYTES,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-local,..grant},native));let(result,identity,_)=result.map_err(|(reason,identity)|{self.group=Some(identity);error(reason)})?;self.group=Some(identity);receipt=result.map_err(error)?;receipt.copied_items=1;receipt.copied_bytes+=local;if self.json.ready(){self.phase=2;}},
            2=>{let Some((bytes,step))=self.json.take(grant)else{return Ok((None,Default::default()));};self.edit=Some(bytes);self.phase=3;receipt=step;},
            3|4=>{if !permit(copy(1+size_of::<usize>()),grant){return Ok((None,Default::default()));}native.checkpoint().map_err(error)?;let edit=self.edit.as_ref().unwrap();let byte=if self.phase==3{semio_framework_replication_edit::canonical::canonical_edit_seal_header_byte(&prepared.edit().id,edit.len()as u64,self.offset)}else{edit.get(self.offset).copied()};if let Some(byte)=byte{self.hash.update(&[byte]);self.offset+=1;}else{self.phase+=1;self.offset=0;}receipt.copied_bytes=1+size_of::<usize>();},
            5=>{let copy=size_of::<semio_framework_hash::Sha256>()+32+32+256+size_of::<u8>();if !permit(super::copy(copy),grant){return Ok((None,Default::default()));}self.digest=self.hash.clone().finalize();self.post_revision=store_post_revision(store,prepared.authority(),self.digest)?;self.hash=semio_framework_hash::Sha256::new();self.phase=6;receipt.copied_bytes=copy;},
            6=>{let local=2*size_of::<Option<String>>();let demand=self.wire_json.next_demand();if grant.maximum_items==0||grant.maximum_copy_bytes<demand.copy_bytes+local||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_depth<demand.depth{return Ok((None,Default::default()));}let identity=self.group.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;let result=semio_framework_os_store_one_item_publication::ArtifactStorePreparedBinding::inspect_group(prepared,identity,grant,|original|self.wire_json.advance(semio_framework_os_store_one_item_publication::lifted_prepared_operation_wire::ArtifactCanonicalTreeSource::view(semio_framework_replication_edit::canonical::EditWireTree::view(original.edit())),DURABLE_OWNED_GROUP_RECOVERY_PACK_MAX_BYTES,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-local,..grant},native));let(result,identity,_)=result.map_err(|(reason,identity)|{self.group=Some(identity);error(reason)})?;self.group=Some(identity);receipt=result.map_err(error)?;receipt.copied_items=1;receipt.copied_bytes+=local;if self.wire_json.ready(){self.phase=7;}},
            7=>{let Some((bytes,step))=self.wire_json.take(grant)else{return Ok((None,Default::default()));};self.wire_edit=Some(bytes);self.phase=8;receipt=step;},
            8=>{let source=BoundSource{wire,group:self.group.as_deref().unwrap(),edit:self.wire_edit.as_deref().unwrap(),digest:&self.digest,generation:wire.base_generation.checked_add(1).ok_or(DurableOwnedGroupDecisionError::InvalidFrontier)?,revision:&self.post_revision};receipt=self.encoder.advance(&source,DurableBoundOneItemOutcomeV1::envelope_id(),DURABLE_OWNED_GROUP_RECOVERY_PACK_MAX_BYTES,grant,native).map_err(error)?;if self.encoder.ready(){self.phase=9;}},
            9=>{let Some((bytes,step))=self.encoder.take(grant)else{return Ok((None,Default::default()));};self.pack=Some(bytes);self.phase=10;receipt=step;},
            10=>{if !permit(copy(1+size_of::<usize>()),grant){return Ok((None,Default::default()));}native.checkpoint().map_err(error)?;let pack=self.pack.as_ref().unwrap();if let Some(byte)=pack.get(self.offset){self.hash.update(&[*byte]);self.offset+=1;}else{self.phase=13;}receipt.copied_bytes=1+size_of::<usize>();},
            11=>{let base=prepared.authority();let texts=base.line_id().map_or(0,str::len)+base.stamped_edit_id().map_or(0,str::len);let authority_bytes=size_of::<ArtifactStoreOneItemLiveAuthority>()+2*size_of::<usize>();let capacity=64+64+texts+authority_bytes;let copy_bytes=size_of::<DurableStoreBindingPlanV1>()+size_of::<ArtifactStoreOneItemLiveAuthority>()+size_of::<semio_framework_hash::Sha256>()+32+capacity;let demand=RetirementDemand{capacity_bytes:capacity,..copy(copy_bytes)};if !permit(demand,grant){return Ok((None,Default::default()));}native.checkpoint().map_err(error)?;native.admit_turn_capacity(grant.maximum_capacity_bytes).map_err(error)?;let mut text=[0u8;64];for(index,byte)in self.hash.clone().finalize().iter().enumerate(){const HEX:&[u8;16]=b"0123456789abcdef";text[2*index]=HEX[usize::from(byte>>4)];text[2*index+1]=HEX[usize::from(byte&15)];}let recovery_pack_sha256=native.copy_text(std::str::from_utf8(&text).unwrap()).map_err(error)?;let rebound_group=native.copy_text(self.group.as_deref().unwrap()).map_err(error)?;native.charge(texts+authority_bytes).map_err(error)?;let authority=Arc::new(base.rebind_group(rebound_group));let plan=DurableStoreBindingPlanV1{authority,group_id:self.group.take(),edit_digest:self.digest,recovery_pack:self.pack.take().unwrap(),recovery_pack_sha256,expected_generation:wire.base_generation,expected_revision:wire.base_revision,post_generation:wire.base_generation.checked_add(1).ok_or(DurableOwnedGroupDecisionError::InvalidFrontier)?,post_revision:self.post_revision};self.phase=12;return Ok((Some(plan),RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,retained_capacity_bytes:capacity,..Default::default()}));},
            _=>return Err(DurableOwnedGroupDecisionError::InvalidOutcome),
        }
        Ok((None,receipt))
    }
    pub fn terminal_is_empty(&self)->bool{self.phase==13&&self.group.is_none()&&self.edit.is_none()&&self.wire_edit.is_none()&&self.pack.is_none()&&self.closing.is_none()&&self.wire_json.terminal_is_empty()&&self.json.terminal_is_empty()&&self.encoder.terminal_is_empty()}
    pub fn close(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.terminal_is_empty(){return Ok(Default::default());}if !self.json.terminal_is_empty(){return Ok(self.json.close(grant));}if !self.wire_json.terminal_is_empty(){return Ok(self.wire_json.close(grant));}if !self.encoder.terminal_is_empty(){return self.encoder.close(grant);}if let Some(owner)=self.closing.as_mut(){let receipt=owner.step(grant)?.progress();if owner.terminal_is_empty(){self.closing=None;}return Ok(receipt);}let demand=copy(size_of::<DurablePlanningOutputV1>()+size_of::<semio_framework_value::retirement::controlled::ControlledRetirement<DurablePlanningOutputV1>>()+size_of::<u8>());if !permit(demand,grant){return Ok(Default::default());}if self.group.is_some()||self.edit.is_some()||self.wire_edit.is_some()||self.pack.is_some(){self.closing=Some(semio_framework_value::retirement::controlled::ControlledRetirement::new(DurablePlanningOutputV1::BoundPlanning{group:self.group.take(),edit:self.edit.take(),wire_edit:self.wire_edit.take(),pack:self.pack.take()}).map_err(|(reason,_)|reason)?);}else{self.phase=13;}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})}
}
impl Drop for DurableBoundPlanningV1{fn drop(&mut self){assert!(std::thread::panicking()||(self.group.is_none()&&self.edit.is_none()&&self.wire_edit.is_none()&&self.pack.is_none()&&self.closing.is_none()),"bound planning must transfer or retire every paid output before Drop");}}
